<?php require 'includes/functions.php';
$where=['p.active=1','c.active=1'];$args=[];
if(trim($_GET['q']??'')!==''){$where[]='(p.name LIKE ? OR p.name_en LIKE ?)';$args[]='%'.trim($_GET['q']).'%';$args[]='%'.trim($_GET['q']).'%';}
if((int)($_GET['category']??0)>0){$where[]='p.category_id=?';$args[]=(int)$_GET['category'];}
foreach(['min'=>'>=','max'=>'<='] as $key=>$op)if(isset($_GET[$key])&&is_numeric($_GET[$key])&&$_GET[$key]>=0){$where[]="p.price $op ?";$args[]=$_GET[$key];}
if(isset($_GET['featured']))$where[]='p.featured=1';
$sql=implode(' AND ',$where);$sort=['low'=>'p.price ASC','high'=>'p.price DESC','new'=>'p.id DESC'][$_GET['sort']??'new']??'p.id DESC';
$count=(int)q("SELECT COUNT(*) FROM products p JOIN categories c ON c.id=p.category_id WHERE $sql",$args)->fetchColumn();$pages=max(1,(int)ceil($count/12));$page=max(1,min($pages,(int)($_GET['page']??1)));$offset=($page-1)*12;
$products=q("SELECT p.* FROM products p JOIN categories c ON c.id=p.category_id WHERE $sql ORDER BY $sort LIMIT 12 OFFSET $offset",$args)->fetchAll();require 'includes/header.php'; ?>
<div class="page-heading"><span class="eyebrow"><?=e(t('เลือกสิ่งดี ๆ ให้ทุกวันของครอบครัว'))?></span><h1><?=e(t('สินค้าสำหรับคนสำคัญ'))?></h1><p><?=e(t('เลือกของชิ้นโปรดให้ลูกน้อย · พบ'))?> <?=$count?> <?=e(t('รายการ'))?></p></div>
<form class="filters" method="get"><input name="q" value="<?=e($_GET['q']??'')?>" placeholder="<?=e(t('ค้นหาสินค้า'))?>"><select name="category"><option value=""><?=e(t('ทุกหมวดหมู่'))?></option><?php foreach(q('SELECT * FROM categories WHERE active=1') as $c): ?><option value="<?=$c['id']?>" <?=($c['id']==($_GET['category']??0))?'selected':''?>><?=e(localized_name($c))?></option><?php endforeach ?></select><input type="number" min="0" step="0.01" name="min" placeholder="<?=e(t('ราคาต่ำสุด'))?>" value="<?=e($_GET['min']??'')?>"><input type="number" min="0" step="0.01" name="max" placeholder="<?=e(t('ราคาสูงสุด'))?>" value="<?=e($_GET['max']??'')?>"><select name="sort"><?php foreach(['new'=>'ใหม่ล่าสุด','low'=>'ราคาต่ำไปสูง','high'=>'ราคาสูงไปต่ำ'] as $v=>$label): ?><option value="<?=$v?>" <?=($_GET['sort']??'new')===$v?'selected':''?>><?=e(t($label))?></option><?php endforeach ?></select><button><?=e(t('ค้นหา'))?></button></form><div class="grid"><?php foreach($products as $p)card($p);if(!$products)echo '<p>ไม่พบสินค้าที่ตรงกับการค้นหา</p>'; ?></div><div class="pagination"><?php for($i=1;$i<=$pages;$i++): ?><a class="<?=$i===$page?'selected':''?>" href="?<?=e(http_build_query(array_merge($_GET,['page'=>$i])))?>"><?=$i?></a><?php endfor ?></div><?php require 'includes/footer.php'; ?>
